from gpiozero import PWMOutputDevice
import RPi.GPIO as GPIO
import sys

# Configure the BCM pin layout for the Raspberry Pi header
GPIO.setmode(GPIO.BCM)

# PWM channels for the three known servo actuators
SERVO_CHANNELS = {"base": 9, "lock": 10, "grabber": 11}

def configure_servo(channel_number):
    """Create and return a configured PWM servo device."""
    # Each channel drives one servo actuator
    return PWMOutputDevice(channel_number, frequency=50)

def apply_command(servo_device, requested_position):
    """Apply a commanded position to a servo device safely."""
    # Clamp the value into the valid 0..1 range for PWM duty
    clamped_value = max(0.0, min(1.0, requested_position))
    servo_device.value = clamped_value

def main():
    """Parse command-line positions and drive the servos."""
    # Build the PWM devices for each actuator
    servo_devices = {name: configure_servo(channel)
                     for name, channel in SERVO_CHANNELS.items()}
    try:
        # Apply every named position argument
        for position_name, position_value in sys.argv[1:].items():
            servo_devices.get(position_name, None).value = position_value
    except ValueError as error:
        print("Invalid position value:", error)
    finally:
        # Release every servo device on shutdown
        for servo_device in servo_devices.values():
            servo_device.close()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

