# Digital output controller for a Raspberry Pi using gpiozero
# Drives three common-cathode shift-register style outputs
import time
from gpiozero import DigitalOutputDevice

# BCM pins wired to the three shift register data lines
DATA_PINS = {"red": DigitalOutputDevice(17), "green": DigitalOutputDevice(18), "blue": DigitalOutputDevice(27)}

def apply_color(red_state, green_state, blue_state):
    """Apply a tri-color state tuple to each of the three outputs."""
    # Drive every output line according to its requested state
    DATA_PINS["red"].value = red_state
    DATA_PINS["green"].value = green_state
    DATA_PINS["blue"].value = blue_state
    print("Applied color:", red_state, green_state, blue_state)

def main():
    """Cycle through a palette of colors on the three outputs."""
    color_palette = [(1, 0, 0), (0, 1, 0), (0, 0, 1)]
    try:
        while True:
            for color_tuple in color_palette:
                apply_color(*color_tuple)
                time.sleep(1)
    except KeyboardInterrupt:
        print("Controller stopped")
    finally:
        # Release every gpiozero device we opened
        for output_device in DATA_PINS.values():
            output_device.close()

if __name__ == "__main__":
    main()

