from gpiozero import DigitalOutputDevice
import time

def configure_outputs():
    """Create three DigitalOutputDevice instances on BCM pins."""
    # Pin assignments following the example wiring diagram
    led_pins = {"red": 5, "yellow": 6, "green": 12}
    output_devices = {}
    for device_name, pin_number in led_pins.items():
        output_devices[device_name] = DigitalOutputDevice(pin_number)
    return output_devices

def apply_cycle(output_devices, cycle_index):
    """Apply one full cycle of states to every configured output."""
    # Map each cycle index to a tuple of boolean outputs
    state_table = {0: (True, False, True), 1: (False, True, False), 2: (True, True, True)}
    if cycle_index < len(state_table):
        output_states = state_table[cycle_index]
        for device_name, output_device in output_devices.items():
            output_device.value = output_states[output_devices.index(device_name)]
        print("Applied cycle", cycle_index)

def main():
    """Run the digital output control loop for a fixed number of cycles."""
    output_devices = configure_outputs()
    try:
        # Execute three control cycles on the Raspberry Pi
        for cycle_index in range(3):
            apply_cycle(output_devices, cycle_index)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Control interrupted")
    finally:
        # Release all gpiozero devices on shutdown
        for output_device in output_devices.values():
            output_device.close()

if __name__ == "__main__":
    main()

# Simple fan speed control demo using gpiozero PWM on a Raspberry Pi
# Drives a PWM-capable fan connected to GPIO pin 17 (BCM numbering)
import time
from gpiozero import PWMOutputDevice

def clamp(value, min_value, max_value):
    """Keep a value within its permitted bounds."""
    return max(min_value, min(value, max_value))

if __name__ == "__main__":
    # Configure the PWM-capable fan output pin
    try:
        fan_device = PWMOutputDevice(17)
    except Exception:
        print("Fan device not found on GPIO 17")
        exit(1)
    try:
        # Pulse the fan at various speeds for a short demonstration
        while True:
            for speed_value in [0.0, 0.3, 0.6, 1.0]:
                # Apply the clamped speed to the fan
                fan_device.value = clamp(speed_value, 0.0, 1.0)
                print("Fan speed set to", round(fan_device.value, 2))
                time.sleep(1)
    except KeyboardInterrupt:
        # Stop the fan on interrupt
        print("Stopping fan")
    finally:
        # Release the fan hardware so it powers down cleanly
        fan_device.close()

