# -*- coding: utf-8 -*-
"""
Control a set of Raspberry Pi GPIO pins as PWM outputs.
"""
import time
import sys
from gpiozero import PWMOutputDevice

# Pin assignments using BCM numbering
PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

def apply_pwm(pwm_device, pwm_value):
    """Apply a PWM value to a single PWMOutputDevice."""
    try:
        pwm_device.value = pwm_value
        return True
    except Exception as e:
        print(f"Error setting PWM on pin {pwm_device.pin}: {e}", file=sys.stderr)
        return False

def report_state(pwm_devices, pwm_values):
    """Print the current PWM state to stdout."""
    print("State:", " ".join(f"{pin}={value:.2f}" for pin, value in zip(pwm_devices, pwm_values)))

def main():
    """Main entry point for the PWM controller."""
    pwm_devices = []
    try:
        # Initialize PWM devices
        for pin_number in PWM_PINS:
            pwm_device = PWMOutputDevice(pin_number)
            pwm_devices.append(pwm_device)

        # Main loop
        while True:
            report_state(pwm_devices, [0.0] * len(pwm_devices))
            time.sleep(1)

    except KeyboardInterrupt:
        print("PWM controller stopped by user.")
    except Exception as e:
        print(f"Unhandled exception: {e}", file=sys.stderr)
    finally:
        # Release all PWM devices
        for pwm_device in pwm_devices:
            try:
                pwm_device.close()
            except Exception:
                pass
        sys.exit(0)

if __name__ == "__main__":
    main()

